def find_convenient_fingering(n, notes):
    # Initialize the fingers array with default values
    fingers = [0] * n

    # Try to assign fingers starting from finger 1 to finger 5
    for start_finger in range(1, 6):
        fingers[0] = start_finger
        valid = True

        for i in range(1, n):
            if notes[i] > notes[i - 1]:
